void ekf_clip_covariance(void) {
#if REMOTE_SENSING_EKF_CLIP_P
	// Clip diagonal covariance elements to prevent over-confidence or instability
	for (int i = 0; i < N_STATES; i++) {
			// Diagonal element is at index i*(i+1)/2+i
			int idx = i * (i + 1) / 2 + i;
			if (P[idx] < REMOTE_SENSING_EKF_P_MIN) {
					P[idx] = REMOTE_SENSING_EKF_P_MIN;
			}
			if (P[idx] > REMOTE_SENSING_EKF_P_MAX) {
					P[idx] = REMOTE_SENSING_EKF_P_MAX;
			}
	}
#endif
}
